           THEN 'CRITICAL'
         WHEN (a.eff_current_cost - a.eff_previous_cost) / NULLIF(a.eff_previous_cost, 0) * 100 >= {{ param('cost_chargeback_by_service', 'warn_increase_pct', 25) }}
           THEN 'WARN'
         ELSE 'OK'
       END AS status,
       CASE
         WHEN s.snapshot_start > dateadd(day, -({{ w }} * 2), {{ audit_today() }}) THEN 'previous_window_not_covered'
